class Solution { public: vector<int> addNegabinary(vector<int>& arr1,vector<int>& arr2){vector<int> reversed;int i=arr1.size()-1,j=arr2.size()-1,carry=0;while(i>=0||j>=0||carry){int sum=carry+(i>=0?arr1[i--]:0)+(j>=0?arr2[j--]:0),bit=sum&1;reversed.push_back(bit);carry=-(sum-bit)/2;}while(reversed.size()>1&&reversed.back()==0)reversed.pop_back();reverse(reversed.begin(),reversed.end());return reversed;} };
